// Nodo Code "Configuracion".
//
// Unico lugar del workflow donde viven los identificadores.
//
// El secreto del webhook NO esta aca: vive en una credencial Header Auth
// del nodo Reserva nueva. Tenerlo en el codigo significaba que cada
// reimportacion del workflow lo pisaba con el placeholder, y ademas viajaba
// en el JSON que se sube al repositorio. Todos los nodos
// que hablan con Notion arman su URL desde aca, en vez de tener el ID de la
// base escrito adentro: si una base se muda o se duplica para un ambiente de
// prueba, se cambia en un solo lugar.
//
// Los valores se leen primero de las variables de entorno de n8n y recien
// despues del literal, asi la misma exportacion del workflow sirve para
// produccion y para pruebas sin editar nodos. El acceso a $env puede estar
// bloqueado segun la instancia, por eso va protegido.

const leerEnv = (clave, porDefecto) => {
  try {
    return $env[clave] || porDefecto;
  } catch {
    return porDefecto;
  }
};

const bases = {
  politicas: leerEnv('ARRECIFE_DB_POLITICAS', '3c119da0dec980be8594c3080b55c1d6'),
  turnos: leerEnv('ARRECIFE_DB_TURNOS', '3c119da0dec980748fbad1f52292f811'),
  reservas: leerEnv('ARRECIFE_DB_RESERVAS', '3c119da0dec98087b386ed1a5e21a39e'),
  errores: leerEnv('ARRECIFE_DB_ERRORES', '3c119da0dec98097b4d8c21f9f9fc137'),
};

// Rango del dia de la reserva, en hora de Montevideo.
//
// Notion compara fechas en UTC: una reserva de las 21:00 -03:00 queda
// guardada como el dia SIGUIENTE en UTC, asi que filtrar por
// { equals: "2028-04-22" } no devuelve ninguna reserva de cena. Y el turno
// de cena va de 19:30 a 00:00, o sea casi todas. Con eso roto, la ocupacion
// daba siempre 0 y los duplicados de noche no se detectaban nunca.
//
// Por eso se filtra por rango con el offset explicito en vez de por
// igualdad de fecha.
const fechaPedida = $('Reserva nueva').first().json.body.datos.fecha;
const siguiente = new Date(new Date(`${fechaPedida}T12:00:00Z`).getTime() + 86400000)
  .toISOString()
  .slice(0, 10);

const rangoDia = {
  desde: `${fechaPedida}T00:00:00-03:00`,
  hasta: `${siguiente}T00:00:00-03:00`,
};

return [
  {
    json: {
      bases,
      rangoDia,
      // Destinatario de los avisos. Al reimportar el workflow los nodos
      // vuelven al valor por defecto, asi que tenerlo en un solo lugar
      // reduce a uno los nodos que hay que retocar.
      chatId: leerEnv('ARRECIFE_CHAT_ID', 'PEGA-ACA-TU-CHAT-ID'),
      // Horas que espera una reserva en revision antes de vencer.
      horasParaVencer: Number(leerEnv('ARRECIFE_HORAS_VENCIMIENTO', 4)),
    },
  },
];

// Nodo Code "Preparar analisis" (este archivo se llama igual que el nodo).
//
// Entrada: la respuesta cruda de Notion al consultar Politicas_Arrecife.
//
// El filtro Activo se aplica aca y no en la consulta: el filtro por
// propiedad venia fallando desde el nodo HTTP de n8n con "Could not find
// property with name or id: Activo", aunque el mismo request funciona
// contra la API. Con 23 politicas traerlas todas y filtrar en JS no cuesta
// nada y saca una pieza fragil del medio.
//
// Arma el contexto RAG y ademas el cuerpo COMPLETO de la llamada a la API
// de Anthropic. El nodo HTTP despues solo lo serializa: armar ese JSON a
// mano dentro de una expresion de n8n es fragil y no se puede probar.
//
// Ojo: la title de Politicas_Arrecife se llama "Nombre", no "Tema". Leer
// "Tema" devuelve undefined y las politicas llegan como "(sin tema)".

// n8n entrega la respuesta HTTP de Notion en formas distintas segun la
// configuracion del nodo: un item con { results: [...] }, un item por
// pagina ya desarmada, o —si esta activo "Include Response Headers and
// Status"— envuelta en { body: { results: [...] } }. Se aceptan las tres.
//
// Cuando esto fallaba, el array quedaba vacio y Claude analizaba la
// reserva sin ninguna politica: escribia "no hay politicas cargadas" y
// bajaba la confianza por no poder contrastar nada. El workflow no daba
// error, solo decidia peor.
const items = $input.all();
const todas = [];
for (const item of items) {
  const j = item.json || {};
  if (Array.isArray(j.results)) todas.push(...j.results);
  else if (Array.isArray(j.body?.results)) todas.push(...j.body.results);
  else if (j.properties) todas.push(j);
}

const paginas = todas.filter((p) => p.properties?.Activo?.checkbox === true);
const d = $('Reserva nueva').first().json.body.datos;

const texto = (prop) => prop?.rich_text?.[0]?.plain_text || '';
const titulo = (prop) => prop?.title?.[0]?.plain_text || '';

const lineas = paginas.map((p) => {
  const nombre = titulo(p.properties.Nombre) || '(sin nombre)';
  const contenido = texto(p.properties.Contenido);
  const categoria = p.properties.Categoria?.select?.name || 'General';
  const prioridad = p.properties.Prioridad?.select?.name || '';
  const aviso = p.properties.Requiere_Aviso_Previo?.checkbox ? ' (requiere aviso previo)' : '';
  return `- [${categoria}${prioridad ? '/' + prioridad : ''}] ${nombre}${aviso}: ${contenido}`;
});

const contexto = lineas.length > 0 ? lineas.join('\n') : 'No hay politicas cargadas.';

const system = [
  'Sos un asistente que evalua solicitudes de reserva del restaurante Arrecife (La Paloma, Rocha).',
  '',
  'Los datos de fecha, hora, personas y contacto ya vienen validados desde el formulario: no los reinterpretes ni los corrijas.',
  'Tu unico trabajo es leer el comentario del cliente y contrastarlo con las politicas vigentes.',
  '',
  'Marca requiere_revision_humana = true si el comentario menciona: eventos privados o cumpleanos grandes,',
  'alergias o restricciones alimentarias serias, mascotas, accesibilidad, pedidos que exceden la operativa normal,',
  'o cualquier cosa que contradiga una politica.',
  '',
  'Si no hay nada de eso, confianza = 1 y requiere_revision_humana = false.',
  'La capacidad del salon y el tamano del grupo los chequea el sistema aparte: no los evalues vos.',
  '',
  'POLITICAS VIGENTES DE ARRECIFE:',
  contexto,
].join('\n');

const usuario = [
  `Nombre: ${d.nombre}`,
  `Personas: ${d.personas}`,
  `Fecha: ${d.fechaLabel} (${d.fecha})`,
  `Hora: ${d.hora}`,
  `Zona pedida: ${d.zonaLabel}`,
  `Comentario del cliente: ${d.comentario || 'Ninguno'}`,
].join('\n');

const peticion = {
  model: 'claude-opus-5',
  // Con el razonamiento activado (que en opus-5 viene por defecto), los
  // tokens de pensamiento salen de este presupuesto: 1000 se queda corto y
  // la respuesta se corta a la mitad.
  max_tokens: 4000,
  system,
  // Structured outputs: la respuesta viene validada contra el esquema, asi
  // que no hace falta pedir "devolve solo JSON" ni manejar el caso de que
  // conteste con texto alrededor.
  output_config: {
    // Clasificar una reserva contra 23 politicas no necesita razonar hondo;
    // bajar el esfuerzo recorta latencia y costo.
    effort: 'low',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          requiere_revision_humana: { type: 'boolean' },
          motivo_revision: { type: ['string', 'null'] },
          confianza: { type: 'number' },
          viola_politica: { type: 'boolean' },
          politica_relacionada: { type: ['string', 'null'] },
        },
        required: [
          'requiere_revision_humana',
          'motivo_revision',
          'confianza',
          'viola_politica',
          'politica_relacionada',
        ],
        additionalProperties: false,
      },
    },
  },
  messages: [{ role: 'user', content: usuario }],
};

return [
  {
    json: {
      contexto,
      politicas: lineas.length,
      politicas_totales: todas.length,
      // Diagnostico: si politicas_totales es 0, esto dice que forma tenia
      // la respuesta para poder arreglarla sin adivinar.
      forma_entrada: items.length === 0 ? 'sin items' : Object.keys(items[0].json || {}).join(','),
      peticion,
    },
  },
];

// Nodo Code "Decidir".
//
// Junta las cuatro fuentes y decide la ruta. Cada una se referencia por
// nombre de nodo a proposito: el $json que llega aca es el de Claude, no
// el de la reserva.
//
// La ocupacion NO sale de un campo Ocupacion en Turnos: se calcula
// sumando las personas de las reservas ya confirmadas de esa fecha. Un
// contador guardado se desincroniza en cuanto alguien cancela o carga una
// reserva a mano.

const cuerpo = $('Reserva nueva').first().json.body;
const d = cuerpo.datos;

// El JSON NO esta en content[0]: claude-opus-5 razona por defecto, asi que
// el primer bloque suele ser de tipo "thinking" y el texto viene despues.
// Hay que buscar el bloque de texto, no asumir la posicion.
let ia;
let iaFallo = false;
try {
  const bloques = $('Claude - Analizar').first().json.content || [];
  const texto = bloques.find((b) => b.type === 'text')?.text;
  ia = JSON.parse(texto);
} catch {
  iaFallo = true;
  ia = {
    requiere_revision_humana: true,
    motivo_revision: 'No se pudo analizar la reserva automaticamente',
    confianza: 0,
    viola_politica: false,
    politica_relacionada: null,
  };
}

// Igual que en Preparar analisis: n8n a veces entrega { results: [...] } en
// un item y a veces un item por pagina. Se aceptan las dos formas.
const paginasDe = (nodo) => {
  const salida = [];
  for (const item of $(nodo).all()) {
    const j = item.json || {};
    if (Array.isArray(j.results)) salida.push(...j.results);
    else if (Array.isArray(j.body?.results)) salida.push(...j.body.results);
    else if (j.properties) salida.push(j);
  }
  return salida;
};

const turnos = paginasDe('Notion - Turno de la fecha');
const confirmadas = paginasDe('Notion - Reservas confirmadas');

const turnoPagina = turnos[0] ?? null;
const capacidad = turnoPagina?.properties?.Capacidad_Total?.number ?? null;
const ocupacion = confirmadas.reduce((suma, p) => suma + (p.properties?.Personas?.number || 0), 0);
// Sin turno cargado para esa fecha no se bloquea: se asume que hay lugar y
// que el encargado lo revisara si hace falta.
const hayLugar = capacidad === null ? true : ocupacion + d.personas <= capacidad;

// Mismo telefono, misma fecha y ya confirmada: es la misma reserva mandada
// dos veces, no una nueva.
const telefono = String(d.telefono || '').replace(/\D/g, '');
const duplicada = confirmadas.some((p) => {
  const otro = p.properties?.Telefono?.rich_text?.[0]?.plain_text || '';
  return String(otro).replace(/\D/g, '') === telefono;
});

// Cuantas politicas vio realmente el analisis. Si son cero, Claude
// clasifico a ciegas: eso es una anomalia del sistema, no algo de la
// reserva, y tiene que quedar registrado en vez de disfrazarse de
// "confianza baja".
const politicasConsultadas = $('Preparar analisis').first().json.politicas ?? 0;
const formaEntrada = $('Preparar analisis').first().json.forma_entrada ?? 'desconocida';

const motivos = [];
if (politicasConsultadas === 0) {
  motivos.push(`ATENCION: el analisis corrio sin politicas cargadas (forma recibida: ${formaEntrada})`);
}
if (ia.requiere_revision_humana) motivos.push(ia.motivo_revision || 'La IA pidio revision');
if (ia.viola_politica) motivos.push(`Politica: ${ia.politica_relacionada || 'sin especificar'}`);
if (d.personas > 10) motivos.push(`Grupo grande (${d.personas} personas)`);
// Si la IA fallo, la confianza es 0 por definicion: agregar "confianza
// baja" al motivo solo confunde a quien lee el aviso.
if (!iaFallo && (ia.confianza ?? 0) < 0.7) motivos.push(`Confianza baja (${ia.confianza})`);
if (!hayLugar) motivos.push(`Sin lugar: ${ocupacion} + ${d.personas} supera ${capacidad}`);

const requiereRevision = motivos.length > 0;

return [
  {
    json: {
      numero: cuerpo.numero,
      recibido: cuerpo.recibido,
      nombre: d.nombre,
      telefono: d.telefono,
      email: d.email,
      fecha: d.fecha,
      fechaLabel: d.fechaLabel,
      hora: d.hora,
      fechaHora: d.fechaHora,
      personas: d.personas,
      zonaLabel: d.zonaLabel,
      comentario: d.comentario,

      duplicada,
      requiere_revision: requiereRevision,
      estado: requiereRevision ? 'Esperando_Aprobacion' : 'Confirmada',
      motivo_revision: motivos.join(' · ') || null,
      confianza: ia.confianza ?? 0,
      politica_relacionada: ia.viola_politica ? ia.politica_relacionada : null,

      capacidad,
      ocupacion,
      hay_lugar: hayLugar,
      politicas_consultadas: politicasConsultadas,
      // Para vincular la reserva con su turno al crearla (relacion en Notion).
      turno_id: turnoPagina?.id ?? null,
      // Lo lee la rama que registra el error: si la IA no contesto, queda
      // constancia en la base Errores en vez de perderse.
      ia_fallo: iaFallo,
    },
  },
];

// Nodo Code "Mensaje al dueno".
//
// Se corre despues de crear la pagina en Notion, asi el mensaje puede
// linkear a la reserva. El $json de entrada es la respuesta de Notion, no
// la decision: por eso la decision se toma por nombre de nodo.

// Telegram interpreta el mensaje segun el parse_mode del nodo, y el de
// n8n usa Markdown por defecto: un guion bajo en el texto —por ejemplo el
// nombre de una politica como "Politica_Reserva"— abre una cursiva que
// nunca cierra, y Telegram rechaza el mensaje entero con "can't parse
// entities". El nodo va en parse_mode HTML, donde solo estos tres
// caracteres son especiales, y aca se escapan.
const escaparHtml = (t) =>
  String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const r = $('Decidir').first().json;
const pagina = $input.first().json;

const lineas = [
  r.requiere_revision ? 'RESERVA A REVISAR' : 'RESERVA CONFIRMADA',
  `#${r.numero} - ${r.nombre}`,
  '',
  `${r.fechaLabel} a las ${r.hora}`,
  `${r.personas} personas - ${r.zonaLabel}`,
];

if (r.comentario) lineas.push(`Comentario: ${r.comentario}`);

lineas.push('', `Tel: ${r.telefono}`);
if (r.email) lineas.push(`Email: ${r.email}`);

if (r.capacidad !== null) {
  lineas.push('', `Ocupacion del turno: ${r.ocupacion} + ${r.personas} de ${r.capacidad}`);
}

if (r.requiere_revision) {
  lineas.push('', `Motivo: ${r.motivo_revision}`);
  lineas.push(`(analizado contra ${r.politicas_consultadas} politicas)`);
  lineas.push(
    '',
    'Para aprobarla o rechazarla, cambia el Estado de la reserva en Notion',
    'a Confirmada o Rechazada. El sistema lo revisa cada 5 minutos y se',
    'vence a las 4 horas sin respuesta.'
  );
}

lineas.push('', `Ver en Notion: ${pagina.url}`);

return [{ json: { ...r, reserva_id: pagina.id, reserva_url: pagina.url, mensaje: escaparHtml(lineas.join('\n')) } }];

// Nodo Code "Retomar datos".
//
// En n8n la salida de cada nodo es la entrada del siguiente, y el nodo de
// Telegram devuelve la respuesta de SU API ({ ok, result: { message_id } }),
// no los datos de la reserva. Sin este nodo, todo lo que viene despues
// evalua $json sobre la respuesta de Telegram:
//
//   - "Requiere aprobacion" lee $json.requiere_revision -> undefined,
//     asi que toda reserva se iba por la rama de confirmada y el loop de
//     aprobacion no corria nunca;
//   - "Tiene email" lee $json.email -> undefined, asi que el mail de
//     confirmacion no se mandaba jamas.
//
// Nada de eso daba error: el workflow terminaba en verde haciendo menos de
// lo que decia hacer.

return [{ json: $('Mensaje al dueno').first().json }];

// Nodo Code "Armar error".
//
// Deja registro en la base Errores cuando el analisis de IA no se pudo
// hacer. La reserva NO se pierde —Decidir la manda a revision humana— pero
// sin este registro el fallo era invisible: el workflow terminaba en verde
// y nadie se enteraba de que Claude no habia contestado.
//
// Se corre despues de crear la reserva a proposito, para poder vincular el
// error con ella (Reserva_Relacionada) en vez de dejar un registro suelto.

const r = $('Mensaje al dueno').first().json;
const bases = $('Configuracion').first().json.bases;

// Lo minimo para poder reproducir el caso, sin volcar la reserva entera:
// telefono y email no hacen falta para depurar por que fallo la IA.
const payload = {
  numero: r.numero,
  fecha: r.fecha,
  hora: r.hora,
  personas: r.personas,
  zona: r.zonaLabel,
  comentario: r.comentario,
  politicas_consultadas: r.politicas_consultadas,
};

// rich_text corta en 2000 caracteres.
const texto = JSON.stringify(payload).slice(0, 1900);

const peticion = {
  parent: { database_id: bases.errores },
  properties: {
    Error_numero: {
      title: [{ text: { content: `Reserva #${r.numero} - fallo el analisis de IA` } }],
    },
    Tipo_Error: { select: { name: 'API_IA_Fallo' } },
    Payload_Original: { rich_text: [{ text: { content: texto } }] },
    Resuelto: { checkbox: false },
    Reserva_Relacionada: { relation: [{ id: r.reserva_id }] },
  },
};

return [{ json: { peticion, numero: r.numero } }];

// Nodo Code "Evaluar aprobacion".
//
// Entrada: la pagina releida desde Notion. Decide si el encargado ya
// respondio o si hay que seguir esperando.
//
// El estado se lee de properties.Estado.select.name, que es la forma que
// devuelve la API de Notion. Leerlo de page['Estado'] devuelve undefined
// y el loop no sale nunca hasta vencer.

const original = $('Mensaje al dueno').first().json;
const pagina = $input.first().json;

const estado = pagina.properties?.Estado?.select?.name || 'Esperando_Aprobacion';

const creado = pagina.created_time || original.recibido;
const horas = (Date.now() - new Date(creado).getTime()) / (1000 * 60 * 60);
// El limite sale de Configuracion, no escrito aca: es una regla de
// negocio que el restaurante puede querer cambiar.
const limite = $('Configuracion').first().json.horasParaVencer ?? 4;
const vencida = horas >= limite;

return [
  {
    json: {
      ...original,
      estado_actual: estado,
      vencida,
      horas_esperando: Math.round(horas * 100) / 100,
      horas_limite: limite,
    },
  },
];

